/**
 * The italic of the family book's serif (1031 §5.1): Source Serif 4 Italic 400,
 * the latin and latin-ext subsets as woff2 (from @fontsource/source-serif-4
 * 5.3.1), declared under the app's renamed family 'Strom Serif' (the Reserved
 * Font Name "Source" asks a modified or subset font to be renamed; see the
 * notices in index.html and README). The upright 400 and 600 come from the
 * app's embedded faces (appFontFaceCss); this italic is embedded only in the
 * book, so the app itself does not grow by it.
 *
 * Generated file: the base64 bodies are the woff2 files unchanged.
 */

const LATIN_ITALIC = '';

const LATIN_EXT_ITALIC = '';

/** The @font-face rules of the book's italic. */
export function bookItalicFontCss(): string {
    return "@font-face { font-family: 'Strom Serif'; font-style: italic; font-weight: 400; font-display: swap; "
        + "src: url(data:font/woff2;base64," + LATIN_EXT_ITALIC + ") format('woff2'); "
        + "unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF; }\n"
        + "@font-face { font-family: 'Strom Serif'; font-style: italic; font-weight: 400; font-display: swap; "
        + "src: url(data:font/woff2;base64," + LATIN_ITALIC + ") format('woff2'); "
        + "unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD; }\n";
}
